chmod +x "$TMP/server/drlink-tcp-egress.py"
chmod +x "$TMP/server/migrate_token.py"
chmod +x "$TMP/server/drlink-mcp-bridge.py"
chmod +x "$TMP/tools/frp-create-client"
chmod +x "$TMP/tools/frp-enrollments"
chmod +x "$TMP/tools/frp-enrollment-revoke"
chmod +x "$TMP/tools/frp-enrollment-purge"
chmod +x "$TMP/tools/frp-enroll-bulk"
chmod +x "$TMP/tools/frp-clients"
chmod +x "$TMP/tools/frp-client-info"
chmod +x "$TMP/tools/frp-services"
chmod +x "$TMP/tools/frp-groups"
chmod +x "$TMP/tools/frp-group-set"
chmod +x "$TMP/tools/frp-release-client"
chmod +x "$TMP/tools/frp-release-service"
chmod +x "$TMP/tools/frp-access"
chmod +x "$TMP/tools/frp-egress"
chmod +x "$TMP/tools/frp-profile"
chmod +x "$TMP/tools/frp-revoke-client"
chmod +x "$TMP/tools/frp-client-set"
chmod +x "$TMP/tools/frp-set-client-installer-url"
chmod +x "$TMP/tools/frp-server-set"
chmod +x "$TMP/tools/frp-server-status"
chmod +x "$TMP/tools/frp-project-update"
chmod +x "$TMP/tools/frp-backup"
chmod +x "$TMP/tools/frp-restore"
chmod +x "$TMP/tools/frp-support-bundle"
chmod +x "$TMP/tools/frp-update"
chmod +x "$TMP/tools/frp-upstream"
chmod +x "$TMP/tools/drlink"
chmod +x "$TMP/tools/frpctl"
if [[ -z "${FRP_EXPECTED_SOURCE_REF:-}" ]]; then
  _frp_bootstrap_ref=""
  if [[ -n "${FRP_BOOTSTRAP_URL:-}" ]]; then
    _frp_bootstrap_ref="$(python3 -c '
import sys
from urllib.parse import unquote, urlsplit
url = sys.argv[1]
host, owner, repo = sys.argv[2:5]
try:
    p = urlsplit(url)
except ValueError:
    raise SystemExit(0)
if p.scheme != "https" or p.hostname != host:
    raise SystemExit(0)
parts = [unquote(x) for x in p.path.split("/") if x]
if len(parts) >= 3 and parts[0] == owner and parts[1] == repo:
    print(parts[2])
' "$FRP_BOOTSTRAP_URL" raw.githubusercontent.com datarelay-labs data-relay-link 2>/dev/null || true)"
  fi
  if [[ -z "$_frp_bootstrap_ref" && -d /proc ]]; then
    _frp_bootstrap_ref="$(python3 - <<'PY' 2>/dev/null || true
import os, re
from urllib.parse import unquote, urlsplit
pat = re.compile(
    r"https://raw\.githubusercontent\.com/datarelay-labs/data-relay-link/"
    r"([^/\s"']+)/dist/bootstrap-server\.sh"
)
pgid = os.getpgid(0)
for name in os.listdir("/proc"):
    if not name.isdigit():
        continue
    try:
        if os.getpgid(int(name)) != pgid:
            continue
        raw = open(f"/proc/{name}/cmdline", "rb").read()
    except (OSError, ProcessLookupError, PermissionError):
        continue
    text = raw.replace(b"\0", b" ").decode("utf-8", "replace")
    m = pat.search(text)
    if not m:
        continue
    ref = unquote(m.group(1))
    if ref and ref not in (".", ".."):
        print(ref)
        break
PY
)"
  fi
  if [[ -n "$_frp_bootstrap_ref" ]]; then
    export FRP_EXPECTED_SOURCE_REF="$_frp_bootstrap_ref"
  fi
  unset _frp_bootstrap_ref
fi
exec "$TMP/install-server.sh" "$@"
